                unset($nullablesSetToNull[$index]);
                $this->setOpenAPINullablesSetToNull($nullablesSetToNull);
            }
        }
        if (!is_null($confidence) && ($confidence > 1.0)) {
            throw new \InvalidArgumentException('invalid value for $confidence when calling PredictionItem., must be smaller than or equal to 1.0.');
